def solve(line: str):
    # Simple CSV parser according to spec.
    fields = []
    i = 0
    n = len(line)
    # Edge case: empty line returns ['']
    if n == 0:
        return ['']
    while i < n:
        field_chars = []
        if line[i] == '"':
            # quoted field
            i += 1
