def solve(coins, amount):
    # Edge case: zero amount requires zero coins
    if amount == 0:
        return 0
    # Remove non-positive coin values to avoid infinite loops
    coins = [c for c in coins if c > 0]
    if not coins:
        return -1
    # Initialize DP array with a sentinel larger than any possible number of coins
    INF = amount + 1  # any value > amount is impossible
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        best = INF
        for c in coins:
            if c <= a:
                # candidate using coin c
                cand = dp[a - c] + 1
                if cand < best:
                    best = cand
        dp[a] = best
    return dp[amount] if dp[amount] != INF else -1

