def solve(grid):
    """Count the number of islands in a binary grid.
    An island is a group of horizontally or vertically adjacent cells with value 1.
    The function returns an integer count. Empty grid returns 0.
    """
    if not grid:
        return 0
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    visited = [[False] * cols for _ in range(rows)]
    count = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1 and not visited[i][j]:
                count += 1
                # iterative DFS using stack
                stack = [(i, j)]
                visited[i][j] = True
                while stack:
                    x, y = stack.pop()
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < rows and 0 <= ny < cols:
                            if grid[nx][ny] == 1 and not visited[nx][ny]:
                                visited[nx][ny] = True
                                stack.append((nx, ny))
    return count

def solve(n):
    if n <= 2:
        return 0
    # Sieve of Eratosthenes up to n-1
    limit = n
    sieve = bytearray(b'\x01') * limit
    sieve[0:2] = b'\x00\x00'  # 0 and 1 not prime
    import math
    for p in range(2, int(math.isqrt(limit - 1)) + 1):
        if sieve[p]:
            step = p
            start = p * p
            sieve[start:limit:step] = b'\x00' * ((limit - 1 - start) // step + 1)
    return sum(sieve)

