    # DP approach for coin change (unbounded knapsack)
    # dp[i] = minimum number of coins to make amount i
    # Use amount+1 as sentinel for impossible (greater than any possible number of coins)
    max_val = amount + 1
    dp = [max_val] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        best = max_val
        for c in coins:
