def solve(matrix):
    # Empty matrix determinant is defined as 1
    if not matrix:
        return 1
    n = len(matrix)
    # Ensure square
    for row in matrix:
        if len(row) != n:
            raise ValueError('Non-square matrix')
    # Make a copy to avoid mutating input
    A = [row[:] for row in matrix]
    det_sign = 1
    prev = 1
    for k in range(n-1):
        # Pivot handling
        if A[k][k] == 0:
            # Find a row to swap
            swap_row = -1
            for i in range(k+1, n):
                if A[i][k] != 0:
                    swap_row = i
                    break
            if swap_row == -1:
                return 0
            A[k], A[swap_row] = A[swap_row], A[k]
            det_sign = -det_sign
        pivot = A[k][k]
        for i in range(k+1, n):
            for j in range(k+1, n):
                # Fraction-free elimination (Bareiss)
                A[i][j] = (A[i][j] * pivot - A[i][k] * A[k][j]) // prev
            A[i][k] = 0
        prev = pivot
    return det_sign * A[n-1][n-1]

