def solve(path):
    """Simplify an absolute Unix file path.
    Steps: split by '/', process tokens using a stack.
    """
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            # if stack empty, stay at root
        else:
            stack.append(part)
