def solve(n, edges):
    """Return the smallest total weight of a path from node 0 to node n-1 in an undirected weighted graph.
    If no such path exists, return -1. Uses Dijkstra's algorithm.
    """
    import heapq
    if n <= 0:
        return -1
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for a, b, w in edges:
        if 0 <= a < n and 0 <= b < n:
            adj[a].append((b, w))
            adj[b].append((a, w))
    # Dijkstra
    dist = [float('inf')] * n
    dist[0] = 0
    pq = [(0, 0)]  # (distance, node)
    while pq:
        d, u = heapq.heappop(pq)
        if d != dist[u]:
            continue
        if u == n - 1:
            break
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    return dist[n - 1] if dist[n - 1] != float('inf') else -1

