import heapq

def solve(n, edges):
    if edges is None:
        edges = []
    # adjacency list and indegree
    adj = [[] for _ in range(n)]
    indeg = [0] * n
    for edge in edges:
        if not isinstance(edge, (list, tuple)) or len(edge) != 2:
            continue
        a, b = edge
        if not (isinstance(a, int) and isinstance(b, int)):
            continue
        if not (0 <= a < n and 0 <= b < n):
            continue
        adj[a].append(b)
        indeg[b] += 1
    heap = [i for i in range(n) if indeg[i] == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        u = heapq.heappop(heap)
        order.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                heapq.heappush(heap, v)
    if len(order) != n:
        return []
    return order

